from admissions_records import *
def s(url,en,ru):return S(url,L(en,ru),access='web-html-read')
record('wheaton-college-massachusetts',[route(label=L('Wheaton College, Norton, Massachusetts — first-year','Wheaton College, Norton, Массачусетс — первокурсники'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None,'recommended':6.5},'toefl':{'accepted':True,'scales':[{'period':'legacy','recommended':85}]},'alternatives':L('Recommended PTE 61 or DET 125 with interview. These are recommendations, not published compulsory cutoffs. TOEFL MyBest accepted.','Рекомендуются PTE 61 либо DET 125 с интервью. Это рекомендации, а не опубликованные обязательные пороги. TOEFL MyBest принимается.'),'waiver':L('Four years of successful high-school study entirely in standard English, apart from foreign languages; ESL courses do not count. Review follows application and records submission.','Четыре успешных школьных года полностью на обычном английском, кроме иностранных языков; ESL не подходит. Рассмотрение после подачи заявления и школьных документов.')},academic={'satPolicy':'optional','note':L('International page explicitly makes SAT/ACT optional for admission and scholarship consideration.','Международная страница прямо называет SAT/ACT необязательными для поступления и рассмотрения стипендии.')},sources=[s('https://wheatoncollege.edu/admission/apply/firstyear/','Wheaton MA first-year English recommendations','Wheaton MA: языковые рекомендации первокурсникам'),s('https://www.wheatoncollege.edu/admission/apply/international/','Wheaton MA international checklist and optional tests','Wheaton MA: международные документы и необязательные тесты')])],'Preserved recommended English scores as recommendations and kept Massachusetts distinct from Illinois.', ['Fall 2027-labelled policy, IELTS variant/sections and new TOEFL scale remain unconfirmed.'])

record('wheaton-college-illinois',[route(label=L('Wheaton College, Illinois — international undergraduate','Wheaton College, Иллинойс — международный бакалавриат'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':None},'toefl':{'accepted':True},'alternatives':L('The catalogue prints IELTS Academic 7–8 or higher and legacy TOEFL 95–105 or higher, without resolving the range into one cutoff. Other options: CEFR C1, DET 125, ACT English 26, SAT Reading/Writing 530 or the stated CLT language result.','Каталог указывает IELTS Academic 7–8 и выше и прежний TOEFL 95–105 и выше, не уточняя единый порог диапазона. Другие варианты: CEFR C1, DET 125, ACT English 26, SAT Reading/Writing 530 либо указанный языковой результат CLT.'),'waiver':L('School-history route requires recent qualifying English-medium study, English grade B or better and good academic performance together. Native-speaker/citizenship exemption has a specified country list.','Школьный маршрут требует одновременно недавнего подходящего обучения на английском, оценки English B и выше и хорошей успеваемости. Для освобождения носителей по гражданству задан список стран.')},academic={'satPolicy':'conditional','note':L('SAT, ACT or CLT required for homeschool/non-accredited secondary schools; other applicants are referred to current application instructions. No universal optional rule is inferred from that referral.','SAT, ACT либо CLT обязателен для домашнего/неаккредитованного школьного образования; остальных направляют к текущим инструкциям подачи. Из этой ссылки не выводится универсальный test-optional.')},documents=[L('School transcript, academic/Christian faith references and programme-specific Conservatory audition; international financial verification before a decision.','Школьные оценки, академическая/христианская рекомендация и прослушивание Conservatory по программе; международное финансовое подтверждение до решения.')],sources=[S('https://catalog.wheaton.edu/undergraduate/admissions/admissions.pdf',L('Wheaton IL undergraduate admission catalogue','Wheaton IL: каталог бакалаврского приёма'),pages=[1,2,3,4],access='pdf-read')])],'Excluded pre-college/graduate IELTS thresholds; retained the catalogue’s unresolved score ranges and conditional academic testing.', ['Exact single English cutoff, sections, new TOEFL scale and Fall 2027 general SAT/ACT/CLT policy require confirmation.'])

record('the-college-of-new-jersey',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None,'recommended':7},'toefl':{'accepted':True,'scales':[{'period':'legacy','recommended':90}]},'note':L('The international page requires language evidence based on first language/school instruction, but calls IELTS 7 and TOEFL 90 recommended results.','Международная страница требует языковое подтверждение по родному языку/языку школы, но называет IELTS 7 и TOEFL 90 рекомендуемыми результатами.')},academic={'satPolicy':'conditional','applicability':cycle(L('Through the 2026–2027 admissions cycle','До цикла приёма 2026–2027 включительно'),[2027]),'note':L('Current testing page: optional except seven-year medicine/optometry and Nursing. Engineering SAT Math 630/ACT Math 27 are early calculus-placement scores, not admission cutoffs. The international page’s 2025–26 wording is older.','Текущая страница тестов: необязательны, кроме семилетних Medicine/Optometry и Nursing. Engineering SAT Math 630/ACT Math 27 — баллы раннего распределения на calculus, не пороги поступления. Формулировка международной страницы про 2025–26 старее.')},sources=[s('https://admissions.tcnj.edu/applications/international-applicants/','TCNJ international language and school documents','TCNJ: международные языковые и школьные документы'),s('https://admissions.tcnj.edu/applications/test-optional/','TCNJ current academic testing and exceptions','TCNJ: актуальные академические тесты и исключения')])],'Separated recommended language scores, current academic exceptions and calculus placement.', ['Fall 2027-specific language rules, IELTS variant/sections and TOEFL new scale remain unconfirmed.'])

record('baruch-college',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':6.5},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':80}]},'alternatives':L('CUNY undergraduate comparison table: Baruch PTE Academic 53 or DET 105. Applies to temporary-visa applicants educated in a non-English environment; not graduate Zicklin requirements.','Таблица бакалавриата CUNY: Baruch PTE Academic 53 либо DET 105. Для временной визы и образования в неанглоязычной среде; не требования магистратуры Zicklin.')},academic={'satPolicy':'optional','note':L('Current CUNY undergraduate application instructions allow applicants to choose SAT/ACT submission; exact Fall 2027 cycle is not stated there.','Текущие инструкции бакалавриата CUNY позволяют выбирать подачу SAT/ACT; точный цикл Fall 2027 там не указан.')},documents=[L('Complete secondary records, translations and national examination certificates; Baruch recommends a first-year essay. Programme-specific supporting requirements still apply.','Полные школьные документы, переводы и национальные экзамены; Baruch рекомендует эссе первокурсника. Дополнительные требования программы сохраняются.')],sources=[s('https://www.cuny.edu/admissions/undergraduate/apply/toefl/','CUNY undergraduate Baruch language comparison','CUNY: языковая таблица бакалавриата Baruch'),s('https://www.cuny.edu/admissions/undergraduate/apply/','CUNY first-year academic tests and foreign records','CUNY: академические тесты первокурсника и зарубежные документы')])],'Used the actual Baruch undergraduate row and current CUNY optional testing, without extending an archived cycle.', ['Fall 2027-specific policy, IELTS sections, new TOEFL scale and individual waiver assessment remain unconfirmed.'])
finish()
